@contextmanager
def make_env(tmp_path):
    rt = RuntimeDir.init(tmp_path / "runtime")
    paths = OrgPaths(root=rt.orgs_dir / "test-org")
    paths.teams_config_path.parent.mkdir(parents=True, exist_ok=True)
    paths.teams_config_path.write_text(
        "teams:\n  engineering:\n    manager: engineering_head\n"
        "    workers: [dev_agent, code_reviewer, qa_engineer]\n"
    )
    db = Database(paths.db_path)
    queue = TaskQueue()
    orch = Orchestrator(db=db, settings=Settings(), paths=paths,
                        slug="test-org", teams=TeamsRegistry.load(paths.root))
    orch.attach_queue(queue)
    try:
        yield orch
    finally:
        # No workers, loops or sessions were started. Drain only this fixture's
        # pending entries, through the production tracked dequeue boundary.
        assert not queue._worker_tasks
        while not queue._queue.empty():
            queue._queue.get_nowait()
            queue._queue.task_done()
        assert not queue._pending_counts
        assert not queue._admission_reservations
        db.close()


@pytest.fixture
def env(tmp_path):
    with make_env(tmp_path) as orch:
        yield orch


def snapshot(orch):
    """All columns of every table, including allocator sequences and raw JSON."""
    db = orch._db
    names = [r[0] for r in db.execute(
        "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
    )]
    return {n: [dict(r) for r in db.execute(f'SELECT * FROM "{n}" ORDER BY rowid')]
            for n in names}


def queue_items(orch):
    q = orch._queue
    assert not q._worker_tasks
    assert not q._admission_reservations
    items = list(q._queue._queue)
    assert q._pending_counts == Counter((s, t) for s, t, _ in items)
    return items


def task(orch, task_id, **kwargs):
    start = datetime.now(timezone.utc)
    orch._db.insert_task(TaskRecord(id=task_id, brief=task_id, **kwargs))
    raw = dict(orch._db.execute("SELECT * FROM tasks WHERE id=?", (task_id,)).fetchone())
    expected = dict(TASK_DEFAULTS, id=task_id, brief=task_id)
    expected.update({k: getattr(v, "value", v) for k, v in kwargs.items()})
    for key in ("created_at", "updated_at"):
        expected[key] = time_binding(raw[key], start, datetime.now(timezone.utc))
    assert raw == expected


def result(orch, *, task_id="TASK-R", agent="code_reviewer",
           session="sess-current", status="completed", verdict="APPROVE"):
    start = datetime.now(timezone.utc)
    next_id = orch._db.execute("SELECT COALESCE(MAX(id),0)+1 FROM task_results").fetchone()[0]
    orch._db.insert_task_result(
        task_id=task_id, agent=agent, session_id=session, status=status,
        verdict=verdict, confidence_score=90,
        output_summary="exact summary\nsecond line", output_dir="output/TASK-R",
        risks_flagged=["risk one", "risk two"], waiting_on_job_ids=["JOB-1"],
    )
    raw = dict(orch._db.execute("SELECT * FROM task_results WHERE id=?", (next_id,)).fetchone())
    assert raw == {
        "id": next_id, "task_id": task_id, "agent": agent, "session_id": session,
        "status": status, "output_summary": "exact summary\nsecond line",
        "decision_json": None, "confidence_score": 90, "learnings": None,
        "risks_flagged": '["risk one", "risk two"]', "duration_seconds": None,
        "token_count": None, "estimated_cost": None, "output_dir": "output/TASK-R",
        "created_at": time_binding(raw["created_at"], start, datetime.now(timezone.utc)),
        "waiting_on_job_ids": '["JOB-1"]', "verdict": verdict, "local_ci": None,
    }


def seed_chain(orch, *, child_status=TaskStatus.COMPLETED,
               agent="code_reviewer", session="sess-current",
               parent_type="task", grandparent=None, final=False):
    task(orch, "TASK-P", assigned_agent=("dev_agent" if parent_type == "subtask"
                                        else "engineering_head"),
         parent_task_id=grandparent, task_type=parent_type,
         session_timeout_seconds=180)
    orch._db.update_task("TASK-P", status=TaskStatus.IN_PROGRESS,
                        block_kind=BlockKind.DELEGATED, note="waiting")
    orch._db.update_task_active_chain("TASK-P", CHAIN_FINAL if final else CHAIN1)
    task(orch, "TASK-R", parent_task_id="TASK-P", assigned_agent=agent,
         task_type="subtask")
    orch._db.update_task("TASK-R", status=child_status, current_session_id=session)


def time_binding(raw, start, end):
    assert isinstance(raw, str)
    parsed = datetime.fromisoformat(raw)
    assert start <= parsed <= end
    return raw


def expect_delta(orch, before, start, *, updates=None, new_task=False,
                 audit=None, queue=()):
    """Explicit changes applied to pristine rows; no field is erased."""
    end = datetime.now(timezone.utc)
    actual = snapshot(orch)
    expected = copy.deepcopy(before)
    for tid, changes in (updates or {}).items():
        row = next(r for r in expected["tasks"] if r["id"] == tid)
        observed = next(r for r in actual["tasks"] if r["id"] == tid)
        for key, value in changes.items():
            if value != "$TIME":
                assert observed[key] == value, (tid, key, observed[key], value)
            row[key] = time_binding(observed[key], start, end) if value == "$TIME" else value
    if new_task:
        observed = next(r for r in actual["tasks"] if r["id"] == "TASK-001")
        row = copy.deepcopy(NEXT_TASK)
        for key in ("created_at", "updated_at"):
            row[key] = time_binding(observed[key], start, end)
        expected["tasks"].append(row)
    if audit:
        prior_id = max((r["id"] for r in before["audit_log"]), default=0)
        row = {"id": prior_id + 1, "task_id": audit[0], "agent": audit[1],
               "action": audit[2], "payload": audit[3],
               "timestamp": time_binding(actual["audit_log"][-1]["timestamp"], start, end)}
        expected["audit_log"].append(row)
        seq = next((r for r in expected["sqlite_sequence"] if r["name"] == "audit_log"), None)
        if seq is None:
            expected["sqlite_sequence"].append({"name": "audit_log", "seq": prior_id + 1})
        else:
            seq["seq"] = prior_id + 1
    assert actual == expected
    assert queue_items(orch) == [("test-org", tid, None) for tid in queue]


def advance(orch, before, start):
    expect_delta(orch, before, start, updates={"TASK-P": {"active_chain": CHAIN2}},
                 new_task=True, audit=("TASK-P", "orchestrator", "chain_auto_advance",
                 '{"leg_index": 2, "spawned_child_id": "TASK-001", "triggering_child_id": "TASK-R", '
                 '"triggering_verdict": "APPROVE", "chain_origin_step_audit_id": 91}'),
                 queue=("TASK-001",))
    stable = snapshot(orch)
    run_step._enqueue_parent_if_waiting(orch, "TASK-R")
    assert snapshot(orch) == stable
    assert queue_items(orch) == [("test-org", "TASK-001", None)]


def wake(orch, before, start):
    expect_delta(orch, before, start,
                 updates={"TASK-P": {"active_chain": None, "updated_at": "$TIME"}},
                 queue=("TASK-P",))
    stable = snapshot(orch)
    run_step._enqueue_parent_if_waiting(orch, "TASK-R")
    assert snapshot(orch) == stable
    assert queue_items(orch) == [("test-org", "TASK-P", None)]


def audit_setup(orch, agent="qa_engineer", parent="TASK-P"):
    task(orch, "TASK-P", assigned_agent="engineering_head")
    task(orch, "TASK-R", assigned_agent=agent, parent_task_id=parent, task_type="subtask")
    orch._db.update_task("TASK-R", status=TaskStatus.COMPLETED, note=FEEDBACK)
    orch._db.insert_audit_log("TASK-R", "orchestrator", "seed", {"literal": "prior"})


@pytest.mark.parametrize("verdict,success", [(v, s) for v in
    ["APPROVE", "PASS", "REQUEST_CHANGES", "unknown-value", "", "   "] for s in [True, False]])
def test_terminal_reader_verdict_audit_literal(env, verdict, success):
    """T1.1: exact explicit bytes, raw feedback/order and zero residue."""
    audit_setup(env)
    result(env, agent="qa_engineer", verdict=verdict)
    before = snapshot(env)
    assert run_step._verdict_for_delegated(env, "TASK-R", success=success) == verdict
    assert snapshot(env) == before
    start = datetime.now(timezone.utc)
    run_step._log_verdict_if_delegated(env, "TASK-R", success=success)
    payload = next(r["expected_payload_raw"] for r in VERDICT_ROWS
                   if r.get("verdict") == verdict and r["success"] == success)
    expect_delta(env, before, start, audit=("TASK-R", "engineering_head", "review_verdict", payload))


@pytest.mark.parametrize("present,success", [(p, s) for p in [False, True] for s in [True, False]])
def test_terminal_reader_verdict_fallback_audit(env, present, success):
    """T1.2: NULL and absent differ from explicit blank."""
    audit_setup(env)
    if present:
        result(env, agent="qa_engineer", verdict=None)
    before = snapshot(env)
    start = datetime.now(timezone.utc)
    run_step._log_verdict_if_delegated(env, "TASK-R", success=success)
    payload = next(r["expected_payload_raw"] for r in VERDICT_ROWS
                   if r.get("report_present") == present and r["success"] == success)
    expect_delta(env, before, start, audit=("TASK-R", "engineering_head", "review_verdict", payload))


@pytest.mark.parametrize("case", ["eligible", "root", "manager", "orchestrator",
                                  "unknown", "null-agent", "empty-agent", "missing"])
def test_terminal_reader_facade_verdict_lookup(env, monkeypatch, case):
    """T1.3/T5.2: retained writer resolves the facade; suppression never calls it."""
    agent = {"manager": "engineering_head", "null-agent": None,
             "empty-agent": "", "orchestrator": "orchestrator", "unknown": "unknown"}.get(case, "qa_engineer")
    audit_setup(env, agent=agent, parent=None if case == "root" else "TASK-P")
    def witness(*args, **kwargs):
        assert case == "eligible", "suppressed caller reached verdict reader"
        return "old helper witness"
    monkeypatch.setattr(run_step, "_verdict_for_delegated", witness)
    before = snapshot(env)
    start = datetime.now(timezone.utc)
    run_step._log_verdict_if_delegated(env, "missing" if case == "missing" else "TASK-R", success=True)
    audit = ("TASK-R", "engineering_head", "review_verdict",
             '{"verdict": "old helper witness", "feedback": "literal feedback\\nsecond line", "reviewed_agent": "qa_engineer"}') if case == "eligible" else None
    expect_delta(env, before, start, audit=audit)


def seed_fanout(orch, *, variant="member", live=TaskStatus.IN_PROGRESS):
    task(orch, "TASK-G", assigned_agent="engineering_head")
    orch._db.update_task("TASK-G", status=TaskStatus.IN_PROGRESS,
                        block_kind=BlockKind.DELEGATED, note="outer waiting")
    raw = {"no-fanout": None, "malformed": "not-json{{[", "empty": "{}",
           "not-member": FANOUT.replace('"TASK-P"', '"TASK-OTHER"')}.get(variant, FANOUT)
    orch._db.update_task_active_fanout("TASK-G", raw)
    task(orch, "TASK-LIVE", parent_task_id="TASK-G", assigned_agent="qa_engineer")
    orch._db.update_task("TASK-LIVE", status=live)


@pytest.mark.parametrize("case", ["root", "missing-grandparent", "manager", "carrier",
                                  "no-fanout", "not-member", "malformed", "empty"])
def test_terminal_reader_failed_parent_classification(env, monkeypatch, tmp_path, case):
    """T2.1/T5.2: same membership does not make a decision owner passive."""
    seed_fanout(env, variant=case)
    grandparent = None if case == "root" else "missing" if case == "missing-grandparent" else "TASK-G"
    seed_chain(env, child_status=TaskStatus.FAILED, grandparent=grandparent,
               parent_type="task" if case == "manager" else "subtask")
    env._db.update_task("TASK-R", note="review tool unavailable")
    result(env, status="blocked", verdict=None)
    before = snapshot(env)
    parent = env._db.get_task("TASK-P")
    assert run_step._is_carrier(env, parent) is (case == "carrier")
    assert snapshot(env) == before
    start = datetime.now(timezone.utc)
    run_step._enqueue_parent_if_waiting(env, "TASK-R")
    if case == "carrier":
        expect_delta(env, before, start, updates={"TASK-P": {
            "active_chain": None, "active_fanout": None, "status": "failed",
            "block_kind": None, "note": FAIL_NOTE, "completed_at": "$TIME", "updated_at": "$TIME"}},
            audit=("TASK-P", "engineering_head", "review_verdict", json.dumps({
                "verdict": "rejected", "feedback": FAIL_NOTE, "reviewed_agent": "dev_agent"})))
        # A separate owned pristine DB/queue supplies the old-path control.
        with make_env(tmp_path / "facade-control") as controlled:
            seed_fanout(controlled, variant=case)
            seed_chain(controlled, child_status=TaskStatus.FAILED,
                       grandparent="TASK-G", parent_type="subtask")
            controlled._db.update_task("TASK-R", note="review tool unavailable")
            result(controlled, status="blocked", verdict=None)
            with monkeypatch.context() as patch:
                patch.setattr(run_step, "_is_carrier", lambda *a: False)
                clean = snapshot(controlled)
                start = datetime.now(timezone.utc)
                run_step._enqueue_parent_if_waiting(controlled, "TASK-R")
                wake(controlled, clean, start)
    else:
        wake(env, before, start)


@pytest.mark.parametrize("parent_type,live", [(p, s) for p in ["task", "subtask"]
                                             for s in [TaskStatus.IN_PROGRESS, TaskStatus.COMPLETED]])
def test_terminal_reader_final_leg_ownership(env, parent_type, live):
    """T2.2: final-leg closure retains the outer barrier and all leaf evidence."""
    seed_fanout(env, live=live)
    seed_chain(env, child_status=TaskStatus.IN_PROGRESS, agent="qa_engineer",
               grandparent="TASK-G", parent_type=parent_type, final=True)
    result(env, agent="qa_engineer", verdict="PASS")
    before = snapshot(env)
    start = datetime.now(timezone.utc)
    run_step._enqueue_parent_if_waiting(env, "TASK-R")
    if parent_type == "task":
        wake(env, before, start)
    else:
        expect_delta(env, before, start, updates={"TASK-P": {
            "active_chain": None, "status": "completed", "block_kind": None,
            "note": "carrier chain complete", "final_output_dir": None,
            "completed_at": "$TIME", "updated_at": "$TIME"}},
            audit=("TASK-P", "engineering_head", "review_verdict",
                   '{"verdict": "approved", "feedback": "carrier chain complete", "reviewed_agent": "dev_agent"}'),
            queue=("TASK-G",) if live == TaskStatus.COMPLETED else ())
        stable = snapshot(env)
        run_step._enqueue_parent_if_waiting(env, "TASK-R")
        assert snapshot(env) == stable
        assert queue_items(env) == ([("test-org", "TASK-G", None)] if live == TaskStatus.COMPLETED else [])


@pytest.mark.parametrize("agent,session", [(a, s) for a in [None, "", "code_reviewer"]
                                         for s in [None, "", "sess-current"]] + [("$NONE", None)])
def test_terminal_reader_partial_fingerprint_chain(env, agent, session):
    """T3.1: genuine absence falls back; complete fingerprints remain exact."""
    if agent == "$NONE":
        before = snapshot(env)
        assert run_step._child_has_modern_fingerprint(None) is False
        assert run_step._child_landed_terminal_report(env, None) is None
        assert run_step._child_has_landed_terminal_result(env, None) is False
        run_step._enqueue_parent_if_waiting(env, "missing")
        assert snapshot(env) == before
        assert queue_items(env) == []
        return
    seed_chain(env, agent=agent, session=session)
    result(env)
    before = snapshot(env)
    modern = agent == "code_reviewer" and session == "sess-current"
    assert run_step._child_has_modern_fingerprint(env._db.get_task("TASK-R")) is modern
