def corrupt_exact(orch, field, value):
    assert field in {"status", "risks_flagged", "waiting_on_job_ids", "decision_json", "confidence_score", "local_ci"}
    orch._db.execute(f"UPDATE task_results SET {field}=? WHERE id=1", (value,))
    orch._db._conn.commit()


def polluted(orch, field, value, *, legacy=False):
    seed_chain(orch, agent=None if legacy else "code_reviewer",
               session=None if legacy else "sess-current")
    result(orch)
    corrupt_exact(orch, field, value)
    if not legacy:
        result(orch, agent="wrong-agent", session="wrong-session")


