@pytest.mark.parametrize("order", ["facade-first", "readers-first"])
def test_terminal_reader_fresh_import_contract(order):
    """T5.1: each import order exposes the same unique definitions, without cycles."""
    root = Path(__file__).resolve().parents[1]
    script = '''
import ast, importlib, inspect, json, pathlib, sys
assert not any(n.startswith('runtime.') for n in sys.modules)
names = ['runtime.orchestrator.run_step', 'runtime.orchestrator.task_terminal_readers']
if sys.argv[1] == 'readers-first': names.reverse()
for name in names: importlib.import_module(name)
facade = importlib.import_module('runtime.orchestrator.run_step')
readers = importlib.import_module('runtime.orchestrator.task_terminal_readers')
selected = ['_verdict_for_delegated', '_is_carrier', '_child_has_modern_fingerprint', '_child_landed_terminal_report']
assert pathlib.Path(facade.__file__).resolve() == pathlib.Path.cwd() / 'runtime/orchestrator/run_step.py'
assert pathlib.Path(readers.__file__).resolve() == pathlib.Path.cwd() / 'runtime/orchestrator/task_terminal_readers.py'
assert sorted(dir(facade)) == ['BlockKind', 'Callable', 'Committed', 'InvalidLineage', 'LostClaim', 'ModuleType', 'NamedTuple', 'Path', 'PendingRetry', 'RetryClaim', 'SpawnOutcome', 'TERMINAL_STATES', 'TYPE_CHECKING', 'TaskStatus', 'TerminalWorktreeReclaimOutcome', '_FAILURE_ROUND_BOUND', '_NO_AUTHENTICATED_REPORT', '_NoAuthenticatedReport', '_PARKED_CARRIER_STATUSES', '_REVISIT_DISCIPLINE_LINES', '_SLICE_RETRY_CEILING', '_TERMINAL_WORKTREE_OUTPUT_LIMIT', '_TERMINAL_WORKTREE_SCANNER_LOCK', '_TERMINAL_WORKTREE_SCANNER_MODULE', '_TERMINAL_WORKTREE_SCANNER_MODULE_NAME', '_TERMINAL_WORKTREE_SCANNER_PATH', '_TERMINAL_WORKTREE_STATUSES', '_TERMINAL_WORKTREE_TIMEOUT_SECONDS', '_V2DecisionDispatchOutcome', '_V2_DECISION_DISPATCH_ADMITTED', '_V2_DECISION_DISPATCH_ORDINARY', '_V2_DECISION_DISPATCH_SKIP', '__annotations__', '__builtins__', '__cached__', '__conditional_annotations__', '__doc__', '__file__', '__loader__', '__name__', '__package__', '__spec__', '_advance_chain_for_completed_child', '_append_followup_system_and_reinvoke', '_auto_revisit_header', '_blocked_jobs_resume_header_if_applicable', '_build_agent_prompt', '_build_prior_steps_from_db', '_carrier_complete_on_chain_complete', '_carrier_fail_immediate', '_carrier_fail_on_verdict_mismatch', '_check_retry_link_required', '_child_has_landed_terminal_result', '_child_has_modern_fingerprint', '_child_landed_terminal_report', '_complete', '_consume_accepted_completion_recovery', '_consume_completion_report', '_consume_completion_report_body', '_current_unresolved_failed_leaves', '_default_agent_for_root', '_enqueue_parent_if_waiting', '_enqueue_task_generation_aware', '_escalate_continued_turn_violation', '_fail', '_fail_terminal_tail', '_fanout_join_header_if_applicable', '_feedback_and_reenqueue', '_format_slice_retry_exhausted_reason', '_handoff_consumed_recovery_terminal_effects', '_inject_fanout_join_context', '_is_already_terminal', '_is_carrier', '_is_continued_turn_decision', '_is_reviewer_omission_error', '_is_slice_retry_exhausted', '_kill_jobs_for_terminating_task', '_legs_out_of_scope', '_list_candidate_agents', '_load_terminal_worktree_scanner', '_log_verdict_if_delegated', '_maybe_post_thread_escalation', '_maybe_post_thread_followup', '_maybe_resume_blocked_task', '_meaningful_stderr', '_payload_dict', '_prepare_attachment_params', '_prepare_workspace_cleanup_reclamation_context', '_reclaim_terminal_task_worktree', '_reject_retry_link_decision', '_reject_reviewer_omission', '_request_pending_v2_publication', '_resolve_completion_result_row_id', '_resolved_escalation_header_if_applicable', '_reviewer_agents_for', '_reviewer_omitted_expectation_error', '_revisit_header_if_applicable', '_run_terminal_worktree_command', '_session_failed_note', '_spawn_fanout_children', '_spend_envelope_as_consumed', '_spend_envelope_as_violation', '_summarize_recent_chain', '_task_matches_authority_v2_refusal_failure', '_terminal_worktree_path_has_symlink', '_terminal_worktree_process_reference', '_terminal_worktree_remaining', '_v2_decision_dispatch_gate', '_v2_report_binds', '_validate_decision_attachments', '_validate_delegate', '_validate_one_leg', '_verdict_for_delegated', '_workspace_cleanup_remainder', '_workspace_cleanup_remainder_fact', 'annotations', 'datetime', 'importlib', 'is_root', 'json', 'load_org_config', 'logger', 'logging', 'os', 'run_step_impl', 'stat', 'subprocess', 'sys', 'threading', 'time', 'timedelta', 'timezone']
for name in selected:
    assert getattr(facade, name) is getattr(readers, name), name
    assert getattr(facade, name).__module__ == readers.__name__, name
    assert getattr(facade, name).__defaults__ is None
    definitions = [(str(p), n.name) for p in pathlib.Path('runtime').rglob('*.py')
                   for n in ast.walk(ast.parse(p.read_bytes()))
                   if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and n.name == name]
    assert len(definitions) == 1, (name, definitions)
assert facade._child_has_landed_terminal_result.__module__ == facade.__name__
assert type(facade._NO_AUTHENTICATED_REPORT) is facade._NoAuthenticatedReport
assert not hasattr(readers, '_NO_AUTHENTICATED_REPORT')
assert not hasattr(readers, 'TaskStatus')
print(json.dumps({'order':sys.argv[1], 'selected':selected}))
'''
    completed = subprocess.run([sys.executable, "-c", script, order], cwd=root,
                               capture_output=True, text=True, timeout=30)
    assert completed.returncode == 0, completed.stdout + completed.stderr
    assert json.loads(completed.stdout)["order"] == order
